import json


def ayarlari_yukle(yol="ayarlar.json"):
    with open(yol, encoding="utf-8") as dosya:
        veri = json.load(dosya)
    return veri["sunucu"]["host"], veri["sunucu"]["port"]


def calistir():
    host, port = ayarlari_yukle()
    print(f"Sunucu: {host}:{port}")


if __name__ == "__main__":
    calistir()

